 "content": "def transform(grid):
    """Expand the single marker into an outward V, then periodic diagonal trails."""
    width = len(grid[0])
    height = width
    markers = [(c, v) for c, v in enumerate(grid[0]) if v != 0]
    if len(markers) != 1 or markers[0][1] != 2:
        raise ValueError("expected one 2 marker in a one-row input")
    center = markers[0][0]
    out = [[0] * width for _ in range(height)]
    for r in range(height):
        # The 2-valued fronts spread one cell per row from the source.
        for c in (center - r, center + r):
            if 0 <= c < width:
                out[r][c] = 2
        # Once the expanding fronts have reached both sides, diagonal 1 trails
        # appear in the congruence class aligned with the original marker.
        if r >= max(center, width - 1 - center) - 3:
            for c in range(width):
                if (c - r - center) % 4 == 0 and out[r][c] == 0:
                    out[r][c] = 1
    return out
