 "content": "def transform(grid):
    width = len(grid[0])
    height = width
    markers = [(c, v) for c, v in enumerate(grid[0]) if v != 0]
    if len(markers) != 1 or markers[0][1] != 2:
        raise ValueError("expected a single 2 in the input row")
    center = markers[0][0]
    out = [[0] * width for _ in range(height)]
    # Two fronts spread diagonally outward from the initial 2.
    for r in range(height):
        for c in (center-r, center+r):
            if 0 <= c < width:
                out[r][c] = 2
    # The trailing 1s form diagonal rays, each next ray starting two rows
    # later and four columns farther left in the c-r diagonal coordinate.
    j = 0
    while 3 + 2*j < height:
        k = center - 4 - 4*j
        start = 3 + 2*j
        for r in range(start, height):
            c = r + k
            if 0 <= c < width and out[r][c] == 0:
                out[r][c] = 1
        j += 1
    return out
